package quatja.com.voronoitest;

import android.content.Context;
import android.graphics.Canvas;
import android.graphics.Color;
import android.graphics.Paint;
import android.os.Bundle;
import android.view.View;
import android.view.ViewGroup;
import android.widget.FrameLayout;

import java.util.ArrayList;
import java.util.List;

import quatja.com.vorolay.VoronoiView;
import quatja.com.vorolay.diagram.VoronoiRegion.VoronoiPoint;

/** Demonstrates points supplied by the application rather than generated by the view. */
public class CustomPointsActivity extends BaseActivity {
    @Override
    protected void onCreate(Bundle state) {
        super.onCreate(state);
        setContentView(R.layout.activity_custom_points);
        FrameLayout container = findViewById(R.id.custom_points_container);
        container.addView(new CustomPointsView(this), new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
    }

    private static class CustomPointsView extends VoronoiView {
        // The five dots on a die: four corners of a square and its center.
        private static final float[][] POSITIONS = {
                {-1f, -1f}, {1f, -1f}, {0f, 0f}, {-1f, 1f}, {1f, 1f}
        };
        private static final int[] COLORS = {
                0xffbde0fe, 0xffffc8dd, 0xffffe5a5, 0xffcdeac0, 0xffd7c5f2
        };
        private final Paint marker = new Paint(Paint.ANTI_ALIAS_FLAG);
        private final List<VoronoiPoint> points = new ArrayList<>();

        CustomPointsView(Context context) {
            super(context);
            setGenerationType(GENERATION_TYPE_CUSTOM);
            enableBorderRoundCorners(false);
            setBorderColor(Color.WHITE);
            setBorderWidth(3f * getResources().getDisplayMetrics().density);
            for (int i = 0; i < POSITIONS.length; i++) {
                View child = new View(context);
                child.setBackgroundColor(COLORS[i]);
                addView(child, new ViewGroup.LayoutParams(
                        ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
            }
        }

        @Override
        protected void onSizeChanged(int width, int height, int oldWidth, int oldHeight) {
            super.onSizeChanged(width, height, oldWidth, oldHeight);
            if (width <= 0 || height <= 0) return;
            points.clear();
            float centerX = width / 2f;
            float centerY = height / 2f;
            float offset = Math.min(width, height) * 0.32f;
            for (float[] position : POSITIONS) {
                points.add(new VoronoiPoint(centerX + position[0] * offset,
                        centerY + position[1] * offset));
            }
            setCustomPoints(points);
        }

        @Override
        protected void dispatchDraw(Canvas canvas) {
            super.dispatchDraw(canvas);
            float density = getResources().getDisplayMetrics().density;
            for (VoronoiPoint point : points) {
                marker.setColor(0xff263238);
                canvas.drawCircle((float) point.x, (float) point.y, 6f * density, marker);
                marker.setColor(Color.WHITE);
                canvas.drawCircle((float) point.x, (float) point.y, 4f * density, marker);
            }
        }
    }
}
